vec3 palette(float t) {
    // generated from http://dev.thi.ng/gradients/
    vec3 a = vec3(0.650, 0.5, 0.31);
    vec3 b = vec3(-0.65, 0.5, 0.6);
    vec3 c = vec3(0.333, 0.278, 0.278);
    vec3 d = vec3(0.660, 0.0, 0.667);

    return a + b * cos(6.28318 * (c * t + d));
}


// from https://iquilezles.org/articles/distfunctions2d/
float ndot(vec2 a, vec2 b ) { return a.x * b.x - a.y * b.y; }
float sdRhombus( in vec2 p, in vec2 b ) {
    p = abs(p);
    float h = clamp( ndot(b - 2.0 * p,b) / dot(b, b), -1.0, 1.0 );
    float d = length( p - 0.5 * b * vec2(1.0 - h,1.0 + h) );

    // d *= sign( p.x * b.y + p.y * b.x - b.x * b.y );
    return d;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    // store uv, which normalizes screen space to -1 <-> 1 in x and y;
    // multiply uv's x dimension by the aspect ratio to remove stretching   
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    vec2 uv0 = uv;
    vec3 finalColor = vec3(0.0);

    for (float i = 0.0; i < 1.0; i += 0.25) {

        uv = fract(uv * 1.33) - 0.5;

        vec2 ra = 2.0 + 0.3 * cos( 1.4 + vec2(1.0 , 2.57) );

        float distance = i * 1.3 + sdRhombus(uv * i, ra) * exp(-length(uv0)) * 2.0 / exp(-sdRhombus(uv * i / 2.1, ra));
        float distanceWorld = sdRhombus(uv0, ra);

        distance = pow(1.0 / distance, 1.1);

        vec3 color = vec3(3.0) - sign(distance);
        color *= -10.0 - exp(-1.0 * abs(distance));
        color = sin(color * 12.0 + iTime ) / 12.0;
        color *= 3.0;

        color = 0.04 / color;

        color *= palette(distanceWorld * iTime * 0.15);

        finalColor += color;

    }


    fragColor = vec4(finalColor,  1.0);

}
